[[ $UID == 2000 && $EUID == 2000 && $PWD == /tmp/parity-case && $HOME == /tmp/parity-home && -O /tmp/parity-case && -O /tmp/parity-home && -r /etc/bashos-parity-vm && -r /sys/class/dmi/id/sys_vendor ]] || { echo 'not a disposable parity guest' >&2; exit 98; }
marker=$(< /etc/bashos-parity-vm); vendor=$(< /sys/class/dmi/id/sys_vendor)
[[ $marker =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ && $vendor == QEMU ]] || { echo 'guest identity mismatch' >&2; exit 98; }
/usr/bin/cp /opt/bashos-parity/harness/helpers/services-auth.py "$HOME/ldap-provider"
/usr/bin/chmod 700 "$HOME/ldap-provider"
BASHUSERDB_VERIFY_FD=3 /usr/bin/setsid "$HOME/ldap-provider" verify external 3< dummy-password > "$HOME/control.out" 2> "$HOME/control.err"
"$HOME/ldap-provider" --check-normal > "$HOME/control.check"
[[ $(< "$HOME/control.check") == 'provider-observation=ok' && ! -s $HOME/control.out && ! -s $HOME/control.err ]] || { echo 'CONTROL-FAILED LDAP adapter' >&2; exit 98; }
/usr/bin/mv "$HOME/ldap.events" "$HOME/control.events"; : > "$HOME/ldap.events"

